			await Topics.events.log(tid, { type: 'backlink', pid: String(postData.pid), uid: String(postData.uid), href: `/post/${postData.pid}` });
		}));
		if (current.length) {
			await db.sortedSetAdd(set, Date.now(), current);
		}
		return added.length + removed.length;
	};

